                    out[r][c] = 0
        return out

    bg = max(set(v for row in grid for v in row),
             key=lambda x: sum(row.count(x) for row in grid))

    # Find connected components of each non-background color.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    q = (y + dy, x + dx)
                    if (0 <= q[0] < h and 0 <= q[1] < w and
                            q not in seen and grid[q[0]][q[1]] == color):
                        seen.add(q)
                        stack.append(q)
            comps.append((color, cells))

    # A large border-touching L is the color key; recolor the nearest
    # small L-shaped component to that color.
    keys = []
    for color, cells in comps:
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        hh, ww = max(ys) - min(ys) + 1, max(xs) - min(xs) + 1
        border = min(ys) == 0 or min(xs) == 0 or max(ys) == h-1 or max(xs) == w-1
        if len(cells) >= 7 and border and hh >= 4 and ww >= 4:
            keys.append((len(cells), color, cells))
    if not keys:
        return out
    _, keycolor, keycells = max(keys)

    candidates = []
    for color, cells in comps:
        if color == keycolor or len(cells) != 3:
            continue
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        if max(ys) - min(ys) != 1 or max(xs) - min(xs) != 1:
            continue
        # Three cells in a 2x2 box form an L.
        dist = min(abs(y-a) + abs(x-b) for y, x in cells for a, b in keycells)
        candidates.append((dist, cells))
    if candidates:
        _, cells = min(candidates, key=lambda item: item[0])
        for r, c in cells:
            out[r][c] = keycolor
    return out
